import codecs
seen = []
def recover(error):
    seen.append(error)
    if len(seen) == 2:
        raise error
    return ('?', -1)
codecs.register_error('encoder-initial-fault', recover)
encoder = codecs.getincrementalencoder('gb2312')('encoder-initial-fault')
try:
    encoder.encode('🐍🐍', True)
except UnicodeEncodeError as error:
    print(error.args)
    print(error.start, error.end, error.reason, error is seen[0], error is seen[1])
encoder.errors = 'strict'
try:
    encoder.encode('A🐍', True)
except UnicodeEncodeError as error:
    print(error.args)
    print(error.start, error.end, error.reason, error is seen[0])

